"""Straight-line evaluation of the sum in Temme's expansion of the
incomplete gamma ratios, for igamTemme.

    python3 testdata/gen/gen_igam_temme_sum.py > zz_igamTemmeSum_gen.go

Reads igamTemmeCoef (incgamma_temme_coeffs.go: the Taylor coefficients in η
of Temme's C_k(η), from SciPy's igam_asymp_coeff.h) and emits

    igamTemmeSum(η, u) = Σ_k C_k(η) u^k,  u = 1/a,

for |η| <= ETA and a >= AMIN, with each row cut at the degree where the
terms left out sum to less than 2^-62 · 0.3 · AMIN^k (|C_0| >= 0.3 there,
and the row is scaled by a^-k), and the rows cut where their bound
max|C_k| · AMIN^-k falls below the same 2^-62 · 0.3. Every row is a
Horner chain of its own (no loop, no branch: the rows overlap in the
pipeline), and the rows are combined by Horner in u.
"""

import os
import re

ETA = 0.34
AMIN = 20.0
TOL = 2.0 ** -62 * 0.3

here = os.path.dirname(os.path.abspath(__file__))
src = open(os.path.join(here, "..", "..", "incgamma_temme_coeffs.go")).read()
body = src[src.index("{", src.index("var igamTemmeCoef")):]
rows = []
for blk in re.findall(r"\{([^{}]*)\}", body):
    nums = re.findall(r"[-+]?\d+\.\d+(?:e[-+]\d+)?", blk)
    if nums:
        rows.append(nums)
assert len(rows) == 25 and all(len(r) == 25 for r in rows)

out = []
for k, r in enumerate(rows):
    mags = [abs(float(c)) * ETA ** n for n, c in enumerate(r)]
    if sum(mags) / AMIN ** k < TOL:
        break
    deg = len(r) - 1
    tail = 0.0
    for n in range(len(r) - 1, 0, -1):
        tail += mags[n]
        if tail >= TOL * AMIN ** k:
            break
        deg = n - 1
    out.append((k, deg, r[: deg + 1]))

print("// Code generated by testdata/gen/gen_igam_temme_sum.py; DO NOT EDIT.")
print()
print("package special")
print()
print("// igamTemmeSum returns Σ_k C_k(η) u^k (u = 1/a) for |η| <= %g, a >= %g:" % (ETA, AMIN))
print("// rows 0..%d, row k cut at degree %s." % (len(out) - 1, ", ".join(str(d) for _, d, _ in out)))
print("func igamTemmeSum(eta, u float64) float64 {")
for k, deg, cs in out:
    expr = cs[deg]
    for n in range(deg - 1, -1, -1):
        expr = "(%s)*eta + %s" % (expr, cs[n]) if n < deg - 1 else "%s*eta + %s" % (expr, cs[n])
    print("\tc%d := %s" % (k, expr))
s = "c%d" % out[-1][0]
for k, _, _ in reversed(out[:-1]):
    s = "c%d + u*(%s)" % (k, s)
print("\treturn %s" % s)
print("}")
